renderer.fragment:
float ck_fill(float d,float aa){return clamp(.5-d/aa,0.,1.);}
float ck_seg(vec2 p,vec2 a,vec2 b,float w){vec2 pa=p-a,ba=b-a;float h=clamp(dot(pa,ba)/dot(ba,ba),0.,1.);return length(pa-ba*h)-w;}
float ck_hand(vec2 p,float a,float len,float tail,float w){vec2 d=vec2(sin(a),cos(a));return ck_seg(p,-d*tail,d*len,w);}
float ck_hands(vec2 p,float R,float ah,float am){return min(ck_hand(p,ah,.5*R,.1*R,.035*R),ck_hand(p,am,.74*R,.12*R,.024*R));}
float ck_box(vec2 p,vec2 b){vec2 d=abs(p)-b;return length(max(d,0.))+min(max(d.x,d.y),0.);}
float ck_tick(float ang,float r,float n,float r0,float r1,float w){float st=6.2831853/n;float l=mod(ang+.5*st,st)-.5*st;vec2 q=vec2(r*sin(l),r*cos(l));return ck_box(q-vec2(0.,.5*(r0+r1)),vec2(w,.5*(r1-r0)));}
void main(){
  vec2 p=(uv-.5)*vec2(iResolution.x/iResolution.y,1.);
  p.y=-p.y;
  float aa=1.5/iResolution.y;
  float R=.5*u_size;
  float r=length(p);
  float ang=atan(p.x,p.y);
  float t=iGlobalTime+u_startTime*60.;
  float TAU=6.2831853;
  float as=TAU*fract(t/60.);
  float am=TAU*fract(t/3600.);
  float ah=TAU*fract(t/43200.);
  float a=ck_fill(r-R,aa);
  vec3 col=u_faceColor*(1.-.1*smoothstep(0.,R,r));
  vec2 so=vec2(.012,-.018)*R;
  float sh=min(ck_hands(p-so,R,ah,am),ck_hand(p-so,as,.84*R,.2*R,.008*R));
  col*=1.-.25*clamp(.5-sh/(R*.03),0.,1.);
  float m=min(ck_tick(ang,r,60.,.86*R,.9*R,.006*R),ck_tick(ang,r,12.,.76*R,.9*R,.018*R));
  m=min(m,abs(r-.97*R)-.03*R);
  col=mix(col,u_markColor,ck_fill(m,aa));
  col=mix(col,u_handColor,ck_fill(ck_hands(p,R,ah,am),aa));
  float s=min(ck_hand(p,as,.84*R,.2*R,.008*R),r-.035*R);
  col=mix(col,u_secondColor,ck_fill(s,aa));
  col=mix(col,u_faceColor,ck_fill(r-.012*R,aa));
  fragColor=vec4(col*a,a);
}
